"""Record the targeted Lifecycle review without changing the adopted catalogue."""
from hashlib import sha256
from scripts.apply_supplier_return_U387 import ROOT, save, append
from scripts.structured_io import read


def main():
    path=ROOT/'connaissance/01-contributions-utilisateur.md'
    assert '## U421\n' not in path.read_text(encoding='utf-8')
    assert '## U422\n' not in path.read_text(encoding='utf-8')
    for identifier,title,quote,scope in [
        ('U421','Distinguer les dimensions de statut d’un Order', "J'ai compris, il ya plusieurs états qui peuvent se recouvrir : une demande peut être \"lancée\" mais en brouillon pour modification. Il faut séparér les dimensions de l'état en différents statuts.", 'Principe de dimensions d’état distinctes et combinables. Le cas lancé/brouillon motive la distinction entre contenu applicable et modification en préparation ; les règles exactes de coexistence, versionnement, suspension et validation ne sont pas encore adoptées. Aucun statut ni comportement ajouté automatiquement.'),
        ('U422','Revoir le nom et le périmètre de Lifecycle', "On doit revoir le lifecycle management qui est mal nommé et mal foutu.", 'Mandat de réexamen ciblé des huit comportements et du nom de D04.o dans l’audit existant. Les deux capacités et le comportement Amendment proposés par Codex restent à arbitrer ; aucun nouveau rattachement ni nom adopté par cette demande.')]:
        append('connaissance/01-contributions-utilisateur.md',f'## {identifier}\n\n**id**\n\n{identifier}\n\n**date**\n\n2026-09-19\n\n**titre**\n\n{title}\n\n**texte**\n\n{quote}\n\n**contexte et portée**\n\n{scope}')
    sources=[]
    for key,title,url,section,finding,limit in [
        ('MS_CHANGE','Approve and confirm purchase orders','https://learn.microsoft.com/en-us/dynamics365/supply-chain/procurement/purchase-order-approval-confirmation','Approval of purchase orders ; Changing purchase orders ; Canceling purchase orders','Avec change management, Request change ramène en Draft ; réapprobation configurable, annulation du reliquat limitée par les réalisations. Journaux des confirmations successives.','Périmètre Purchase Orders ; ne prouve pas que toute exécution continue pendant une révision ni que les dimensions sont indépendantes.'),
        ('MS_IMPACT','Review and accept changes to confirmed purchase orders','https://learn.microsoft.com/en-us/dynamics365/supply-chain/procurement/purchase-order-changes-after-confirmation','The Confirmed purchase orders with changes workspace ; Review changes','Les changements confirmés sont examinés selon leurs impacts directs sur les besoins aval, puis reconfirmés.','Mécanisme produit, pas nouvelle décision FLOW ni preuve de couverture de tous les impacts indirects.'),
        ('MS_FIRM','Firm planned orders','https://learn.microsoft.com/en-us/dynamics365/supply-chain/master-planning/planning-optimization/planned-order-firming','Introduction','Firming transforme les ordres planifiés en commandes d’achat, transfert ou production effectives.','Microsoft emploie aussi release pour cette opération ; FLOW distingue affermissement et autorisation de prise en charge. Pas tous les types d’Orders.'),
        ('MS_HOLD','Manage order holds','https://learn.microsoft.com/en-us/dynamics365/supply-chain/sales-marketing/tasks/manage-order-holds','Set up order hold codes ; Manage orders on hold','Des motifs métier bloquent le traitement expédition ; leur levée autorise la progression.','Le comportement produit concerne les commandes de vente et ne prescrit pas le domaine FLOW.'),
        ('MS_RELEASE','Release to warehouse','https://learn.microsoft.com/en-us/dynamics365/supply-chain/warehousing/release-to-warehouse-process','Release to warehouse overview ; Manual release','Autorisation du traitement entrepôt sur commandes ou lignes, avec création d’objets logistiques.','FLOW distingue autorisation D03 proposée et orchestration D06 ; aucune équivalence complète avec le mécanisme WMS.'),
        ('MS_FREEZE','Master plans overview','https://learn.microsoft.com/en-us/dynamics365/supply-chain/master-planning/master-plans','Time fences in days — Freeze','Le gel temporel empêche la modification d’ordres planifiés dans la période lors du recalcul.','Le gel sélectif FLOW porte des éléments désignés d’Orders ; il ne reprend pas automatiquement toute la time fence Microsoft.')]:
        sources.append(dict(id=key,vendor='Microsoft',product='Dynamics 365 Supply Chain Management',title=title,url=url,edition='Documentation en ligne évolutive',consulted_on='2026-09-19',locator=section,nature='Mécanisme ou processus produit',finding=finding,limits=limit))
    mappings=[]
    for identifier,name,target,reason in [
        ('BHV038','Order Drafting','D04 / Order Change Management','Préparer le contenu avant soumission ; distinguer brouillon initial et révision d’une demande engagée.'),
        ('BHV036','Order Firming','D03 / Order Backlog Control','Engager une intention planifiée dans le carnet ; mobiliser la capacité par type pour établir l’Order applicable. Affermir ne vaut ni approuver un avenant ni libérer.'),
        ('BHV037','Order Freezing','D03 / Order Backlog Control','Protéger les éléments désignés contre les réoptimisations ; ne pas en faire un verrou universel de modification.'),
        ('BHV039','Order Release','D03 / Order Backlog Control','Autoriser la prise en charge individuelle ou collective d’une part de demande ; ne constate pas son démarrage.'),
        ('BHV040','Order Hold & Resume','D03 / Order Backlog Control','Suspendre ou réautoriser une progression désignée ; Process Adaptation traite les conséquences sur les services en cours.'),
        ('BHV041','Order Rescheduling','D04 / Order Change Management','La définition actuelle modifie l’échéance DU BESOIN. Une date de satisfaction calculée relève de Delivery Schedule Decision et de Planning ; une promesse révisée de Promise Management.'),
        ('BHV042','Order Cancellation','D04 / Order Change Management','Retirer le besoin ou son reliquat autorisé. Retirer une affectation ou une sélection d’un scénario ne signifie pas annuler la demande.'),
        ('BHV043','Order Closure','D04 / Order Change Management','Établir la fin de la demande opérationnelle et le devenir du reliquat à partir des faits et engagements. Ce n’est ni constater la seule fin d’une Task ni archiver.')]:
        mappings.append(dict(behavior_id=identifier,name=name,proposed_target=target,reason=reason,status='proposed',preserve_identifier=True))
    proposal=dict(status='proposed',source_refs=['U421','U422','ELM249','CMP160'],catalogue_unchanged=True,catalogue_sha256=sha256((ROOT/'modeles/backlog/model.yaml').read_bytes()).hexdigest(),diagnosis='Lifecycle agrège maturité de la demande, engagement planifié, contrôle de prise en charge et fin du besoin. Les déplacements en bloc masquent ces frontières. Aucun statut ne détermine à lui seul une capacité.',adopted_principle='U421 : distinguer des dimensions d’état combinables, soumises à des contraintes de cohérence.',capabilities=[dict(name='Order Change Management',domain_id='D04',implementation_option='Recentrer D04.o en préservant son identifiant après accord.',definition='Gouverner la préparation et les modifications autorisées des demandes, en distinguant contenu applicable, changements en préparation et effets sur les engagements existants.',decomposition_rationale='Préparer une demande non engagée, réviser une demande engagée, changer son échéance, retirer son reliquat ou établir sa fin ont des effets métier différents. La révision contrôlée évite qu’un brouillon devienne implicitement applicable aux traitements en cours.',naming='Appui sur change management et Purchase order preparation Microsoft ; nom transverse FLOW proposé, pas intitulé d’une capacité Microsoft documentée.',boundary='Les capacités par intention portent parties, clauses et parcours métier. Pas de mutualisation informatique motivant cette capacité. Les décisions spécialisées évaluent les options, D06 gère les conséquences sur les processus.'),dict(name='Order Backlog Control',domain_id='D03',implementation_option='Nouvelle capacité proposée, sans identifiant réservé avant accord.',definition='Gouverner l’engagement des demandes dans le carnet, leur protection contre les réoptimisations et l’autorisation ou la suspension de leur prise en charge.',decomposition_rationale='Firming engage une intention, Freezing protège un contenu désigné, Release autorise une prise en charge, Hold suspend une progression. Ces effets se combinent et ne forment pas les étapes d’un statut unique.',naming='Intitulé descriptif FLOW proposé ; pas d’équivalence lexicale Microsoft établie. Appuis fonctionnels distincts Firming, Hold, Release et Freeze.',boundary='Planning prépare les scénarios ; les décisions calculent les réponses ; Control applique engagements et autorisations ; Process Orchestration coordonne les services. Control ne signifie pas décider une nouvelle stratégie de fulfillment.')],behavior_mapping=mappings,additional_behavior=dict(name='Order Amendment',target='D04 / Order Change Management',status='proposed',definition='Préparer et rendre applicable une modification d’un Order déjà engagé, en préservant la distinction entre proposition, contenu en vigueur et réalisations acquises.',benefit='Permettre la révision contrôlée d’une demande déjà prise en charge sans appliquer silencieusement un brouillon ; exposer impacts, portée et conditions de prise d’effet.',limits='Pas de clone technique imposé, d’exécution simultanée toujours autorisée ni d’approbation humaine systématique. L’impact est établi via les capacités responsables ; compensation et adaptation restent en D06.'),preserved=['Structuring et Split dans D03','Order Archiving dans D03','Capacités par type et leurs comportements métier','Décisions, Planning, affectation, promesse et processus distincts','Un parent par comportement, sans sous-comportement','Pas de nouveau comportement pour chaque statut ou opération CRUD'],market_comparisons=sources,validation_scope='Aucun nom, définition, ajout ou déplacement proposé ici n’est adopté. En cas d’accord : préciser les champs effectivement validés, préserver les identifiants et les empreintes antérieures, puis appliquer le catalogue et ses vues.')
    review=read(ROOT/'modeles/backlog/order-backlog-review.yaml')
    assert 'lifecycle_redesign_U422' not in review
    review['lifecycle_redesign_U422']=proposal
    review['source_refs']=list(dict.fromkeys(review['source_refs']+proposal['source_refs']))
    review['status']='lifecycle_redesign_proposed_U422'
    review['next_arbitration']='Arbitrer Order Change Management en D04, Order Backlog Control en D03, la répartition des huit comportements et le mécanisme Order Amendment. Catalogue courant U420 conservé.'
    save('modeles/backlog/order-backlog-review.yaml',review)
    ann=read(ROOT/'modeles/backlog/order-lifecycle-behaviors.yaml')
    ann['review_U422']=dict(status='proposed',source_refs=proposal['source_refs'],proposal_ref='modeles/backlog/order-backlog-review.yaml#lifecycle_redesign_U422',note='Réexamen ciblé dans l’audit existant. Huit comportements examinés ; aucun changement au catalogue adopté U420.')
    save('modeles/backlog/order-lifecycle-behaviors.yaml',ann)
    agents=ROOT/'AGENTS.md';content=agents.read_text(encoding='utf-8')
    marker='- **Order Lifecycle Management (U349)**'
    assert marker in content
    content=content.replace(marker,'- **Dimensions d’état des Orders (U421/U422)** : distinguer maturité de la demande/révision, engagement, autorisation de prise en charge, suspension, réalisation et conservation. Ces dimensions se combinent sous contraintes ; aucun statut global ni comportement par valeur. Un contenu applicable et une modification en préparation doivent rester distinguables, sans présumer que tout traitement continue pendant la révision. U422 demande le réexamen ciblé de Lifecycle ; noms et répartition proposés dans `order-backlog-review.yaml`, `lifecycle_redesign_U422`, non adoptés. Le catalogue U420 reste courant jusqu’à arbitrage.\n'+marker)
    agents.write_text(content,encoding='utf-8')
    append('marche/elements.md','### ELM249\n\nMicrosoft Dynamics 365 SCM — change management des Purchase Orders, examen des modifications confirmées, Firm planned orders, Manage order holds, Release to warehouse et gel temporel des Master plans. Documentation évolutive, passages primaires consultés le 19 septembre 2026. URL, localisateurs, synthèses et limites dans modeles/backlog/order-backlog-review.yaml, lifecycle_redesign_U422.market_comparisons. Nature : mécanismes et processus produit ; aucune taxonomie de capacités ni preuve installée Beaumanoir.')
    append('marche/comparaisons.md','### CMP160\n\nU421/U422 — Réexamen proposé de Lifecycle : Order Change Management en D04 (préparation et changements du besoin), Order Backlog Control en D03 (affermissement, gel, autorisation et suspension). Huit comportements tracés sans changement de catalogue. Appuis Microsoft ELM249 ; noms transverses FLOW proposés, pas consensus ni catalogue éditeur. Amendment justifié par les effets d’une révision sur une demande déjà engagée. Rescheduling actuel concerne la date du besoin, non la date promise ; Cancellation retire le besoin, non sa seule affectation. La séparation des dimensions n’impose pas leur indépendance ni une architecture de versions particulière. Rapprochement proposé, non validé.')
    assert proposal['catalogue_sha256']==sha256((ROOT/'modeles/backlog/model.yaml').read_bytes()).hexdigest()
    print('U421 principle recorded; U422 proposal recorded; active catalogue unchanged.')


if __name__=='__main__':main()
